package com.highpass.runspot.chat.service;import com.highpass.runspot.auth.domain.User;import com.highpass.runspot.chat.domain.*;import com.highpass.runspot.chat.exception.*;import com.highpass.runspot.chat.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class ChatNoticeService{private final ChatRoomMemberRepository members;private final ChatNoticeRepository notices;
 @Transactional public void put(Long userId,Long roomId,String content){ChatRoomMember host=host(userId,roomId);ChatNotice notice=notices.findByRoomIdAndActiveTrue(roomId).orElse(null);if(notice==null)notices.save(ChatNotice.create(host.getRoom(),host.getUser(),content));else notice.update(content);}
 @Transactional public void delete(Long userId,Long roomId){host(userId,roomId);notices.findByRoomIdAndActiveTrue(roomId).ifPresent(ChatNotice::deactivate);}
 private ChatRoomMember host(Long userId,Long roomId){ChatRoomMember m=members.findByRoomIdAndUserIdAndLeftAtIsNull(roomId,userId).orElseThrow(()->new ChatException(ChatErrorCode.NOT_ROOM_MEMBER));if(m.getRole()!=ChatMemberRole.HOST)throw new ChatException(ChatErrorCode.NOT_ROOM_HOST);return m;}}
